import { Link } from 'react-router-dom';
import Card from '../components/Card';

const subjects = [
  { title: 'DBMS', note: 'Structured query language, normalization, indexing.', color: 'from-blue-800 to-cyan-800 dark:from-blue-200 dark:to-cyan-200' },
  { title: 'OS', note: 'Scheduling, memory allocation, concurrency models.', color: 'from-green-800 to-emerald-800 dark:from-green-200 dark:to-emerald-200' },
  { title: 'CN', note: 'Network topologies, protocols, security basics.', color: 'from-purple-800 to-violet-800 dark:from-purple-200 dark:to-violet-200' },
  { title: 'SE', note: 'Requirements, architecture, testing, agile.', color: 'from-pink-800 to-rose-800 dark:from-pink-200 dark:to-rose-200' },
];

export default function FundamentalsPage() {
  return (
    <div className="space-y-8">
      <Card title="Core subjects" description="Select the foundational subject you want to deepen next.">
        <div className="grid gap-5 sm:grid-cols-2">
          {subjects.map((item) => (
            <Link key={item.title} to={`/topics?subject=${item.title}`}>
              <div className="rounded-[2rem] border border-slate-800 bg-slate-950/90 p-6 hover:border-cyan-500/40 hover:bg-slate-900/95">
                <h3 className="text-xl font-semibold text-white">{item.title}</h3>
                <p className="mt-3 text-slate-400">{item.note}</p>
                <div className="mt-5 inline-flex items-center rounded-full bg-slate-800 px-4 py-2 text-sm text-slate-300">View lessons</div>
              </div>
            </Link>
          ))}
        </div>
      </Card>
    </div>
  );
}
